    /// <summary>Business audit trail — one row per auditable action</summary>
    public DbSet<AuditLog> AuditLog => Set<AuditLog>();
    /// <summary>Change document for configuration and master data</summary>
    public DbSet<ChangeDocumentHeader> ChangeDocumentHeader => Set<ChangeDocumentHeader>();
    /// <summary>Field-level before/after values</summary>
    public DbSet<ChangeDocumentItem> ChangeDocumentItem => Set<ChangeDocumentItem>();
    /// <summary>Read access to personal or restricted data</summary>
    public DbSet<DataAccessLog> DataAccessLog => Set<DataAccessLog>();
    /// <summary>Retention and archiving rule per audit or business object</summary>
    public DbSet<RetentionPolicy> RetentionPolicy => Set<RetentionPolicy>();
    // ---- Reporting metadata [rpt] ----
    /// <summary>Registered report</summary>
    public DbSet<ReportDefinition> ReportDefinition => Set<ReportDefinition>();
    /// <summary>Execution record for auditing and performance analysis</summary>
    public DbSet<ReportExecutionLog> ReportExecutionLog => Set<ReportExecutionLog>();
    /// <summary>Column layout of a report or list</summary>
    public DbSet<ReportLayout> ReportLayout => Set<ReportLayout>();
    /// <summary>Selection parameter of a report</summary>
    public DbSet<ReportParameter> ReportParameter => Set<ReportParameter>();
    /// <summary>Saved selection values for a report</summary>
    public DbSet<ReportVariant> ReportVariant => Set<ReportVariant>();
    // ---- Integration and API management [intg] ----
    /// <summary>Registered API consumer</summary>
    public DbSet<ApiClient> ApiClient => Set<ApiClient>();
    /// <summary>Imported electronic bank statement header</summary>
    public DbSet<BankStatement> BankStatement => Set<BankStatement>();
    /// <summary>Bank statement line and its clearing result</summary>
    public DbSet<BankStatementItem> BankStatementItem => Set<BankStatementItem>();
    /// <summary>Recorded idempotency key and its stored response</summary>
    public DbSet<IdempotencyKey> IdempotencyKey => Set<IdempotencyKey>();
    /// <summary>CSV / Excel import run</summary>
    public DbSet<ImportJob> ImportJob => Set<ImportJob>();
    /// <summary>Rejected row of an import job</summary>
    public DbSet<ImportJobError> ImportJobError => Set<ImportJobError>();
    /// <summary>Received message, stored before processing</summary>
    public DbSet<InboundMessage> InboundMessage => Set<InboundMessage>();
    /// <summary>Outbound endpoint configuration (payroll, bank, logistics)</summary>
    public DbSet<IntegrationEndpoint> IntegrationEndpoint => Set<IntegrationEndpoint>();
    /// <summary>Transactional outbox — events written with the business transaction</summary>
    public DbSet<OutboxMessage> OutboxMessage => Set<OutboxMessage>();
    /// <summary>Delivery attempt of a webhook</summary>
    public DbSet<WebhookDelivery> WebhookDelivery => Set<WebhookDelivery>();
    /// <summary>Subscription of an external system to events</summary>
    public DbSet<WebhookSubscription> WebhookSubscription => Set<WebhookSubscription>();
}
